  employee_id: number;
  emp_number: string;
  full_name: string;
  father_or_husband_name: string | null;
  cnic: string;
  dob: string | null;
  gender: "male" | "female" | "other" | "unknown" | null;
  mobile: string;
  email: string | null;
  address: string | null;
  blood_group: "A+" | "A-" | "B+" | "B-" | "AB+" | "AB-" | "O+" | "O-" | "Unknown" | null;
  department_id: number | null;
  department_name: string | null;
  designation: string;
  specialty: string | null;
  supervisor_id: number | null;
  supervisor_name: string | null;
  base_salary: number;
  contract_type: "Permanent" | "Contract" | "Visiting";
  employment_status: "Draft" | "Awaiting_IT_Provisioning" | "Active" | "Suspended" | "Resigned" | "Terminated";
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  is_clinical_staff: boolean;
  license_type: "PMDC" | "PNC" | "Other" | null;
  license_number: string | null;
