/** Search employees — GET /api/v1/hr/employees (who may call: holders of hr.employee.view). */
export function searchHrEmployees(query?: { q?: string | null; status?: string | null; department_id?: number | null; limit?: number }): Promise<EmployeeSearchItemOut[]> {
  return api<EmployeeSearchItemOut[]>("GET", withQuery(`/hr/employees`, query), undefined);
}

/** Full profile incl. documents, qualifications, submit checklist — GET /api/v1/hr/employees/{employee_id} (who may call: holders of hr.employee.view). */
export function getHrEmployees(employee_id: number): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("GET", `/hr/employees/${employee_id}`, undefined);
}

/** Reporting hierarchy (supervisor tree) — GET /api/v1/hr/org-chart (who may call: holders of hr.employee.view). */
export function orgChart(): Promise<OrgChartNodeOut[]> {
  return api<OrgChartNodeOut[]>("GET", `/hr/org-chart`, undefined);
}

/** Download an employee document — GET /api/v1/hr/employee-documents/{document_id}/download (who may call: holders of hr.document.view). */
export function downloadDocumentHrEmployeeDocuments(document_id: number): Promise<unknown> {
  return api<unknown>("GET", `/hr/employee-documents/${document_id}/download`, undefined);
}

/** Suspend / resign / terminate (login and badges revoked), reinstate or re-join — POST /api/v1/hr/employees/{employee_id}/status (who may call: holders of hr.employee.update). */
export function setStatusHrEmployees(employee_id: number, body: EmploymentStatusIn): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("POST", `/hr/employees/${employee_id}/status`, body);
}

/** Leave balances of an employee — GET /api/v1/hr/employees/{employee_id}/leave-balances (who may call: holders of hr.leave.manage or hr.leave.approve). */
export function empBalances(employee_id: number, query?: { year?: number | null }): Promise<LeaveBalanceOut[]> {
  return api<LeaveBalanceOut[]>("GET", withQuery(`/hr/employees/${employee_id}/leave-balances`, query), undefined);
}

/** Set a leave balance (opening / accrued / carried forward) — PUT /api/v1/hr/leave-balances (who may call: holders of hr.leave.manage). */
export function setBalance(body: BalanceIn): Promise<LeaveBalanceRowOut> {
  return api<LeaveBalanceRowOut>("PUT", `/hr/leave-balances`, body);
}
